function addChick(id,restored=false,nestId=null){const info=chickCatalog.find(entry=>entry.id===id);if(!info||chicks.some(chick=>chick.id===id))return;const index=chicks.length,chick={id,name:info.name,asset:info.asset,x:202,y:restored?430:286,size:65,phase:index*1.8,status:info.status,arrivedAt:restored?-100:state.clock,activity:null,activityCount:0};chicks.push(chick);if(!facilities.some(f=>f.type==="nest"&&f.occupant===id)){const nest=facilities.find(f=>f.id===nestId&&f.type==="nest")||freeNest();if(nest)nest.occupant=id}state.selectedChick=id}
