function pickChickActivity(chick){
 const profile=lifeData[chick.id];if(!profile)return;
 const options=[];
 for(const routine of profile.activities||[]){if(!routine.times.includes(timeSlot()))continue;const places=routine.place==="nest"?facilities.filter(f=>f.type==="nest"&&f.occupant===chick.id):facilities.filter(f=>f.type===routine.place);for(const place of places)if(!chicks.some(other=>other!==chick&&other.activity?.placeId===place.id))options.push({x:place.x+(place.x>195?-30:30),y:place.y+12,label:routine.label,mark:routine.mark,placeId:place.id})}
 const natural=entities.find(e=>e.type===profile.nature?.type&&e.hp>0&&!chicks.some(other=>other!==chick&&other.activity?.placeId===e.id));if(natural)options.push({x:natural.x+(natural.x>195?-43:43),y:natural.y+13,label:profile.nature.label,mark:profile.nature.mark,placeId:natural.id});
 if(!options.length){const nest=facilities.find(f=>f.type==="nest"&&f.occupant===chick.id);options.push({x:nest?.x||195,y:(nest?.y||515)+12,label:"마을 산책",mark:"♪",placeId:nest?.id||null})}
 const choice=options[(chick.activityCount+state.day+chicks.indexOf(chick))%options.length];chick.activityCount++;
 chick.activity={status:"travel",x:Math.max(42,Math.min(348,choice.x)),y:Math.max(310,Math.min(715,choice.y)),label:choice.label,mark:choice.mark,placeId:choice.placeId,until:0};
}
